    var em = world.EntityManager;
    var query = em.CreateEntityQuery(typeof(ScrollOffset));
    var entity = query.GetSingletonEntity();
    
    em.SetComponentData(entity, new ScrollOffset { accumulatedOffset = loadedOffset });
    query.Dispose();
}
